// Uploads a JSON file via the raw upload button on a collection row and asserts no error snackbar appears.
const uploadJsonToCollection = async (page, collectionRow, jsonFilePath) => {
  const uploadInput = collectionRow.locator('input[id^="rawUpload_"]');
  await uploadInput.setInputFiles(jsonFilePath);
  await expect(page.locator('#client-snackbar')).not.toBeVisible({ timeout: 3000 });
};

