test("Test raw JSON upload error cases", async ({
  page,
  authenticatedBetaTesterExtensionId,
}) => {
  await page.goto(
    `chrome-extension://${authenticatedBetaTesterExtensionId}/popup.html#/app/tools/Sna`,
  );

  // Upload Twitter CSV to create a collection row to test against
  const csvPath = path.resolve(
    __dirname,
    "../../tests-assets/TW-TEST-PLAYWRIGHT~TWITTER_export.csv",
  );
  await page.locator('[data-testid="sna-file-upload-input"]').setInputFiles(csvPath);
  await page.locator('[data-testid="sna-social-media-icon-twitter"]').click();
  await page.locator('[data-testid="sna-new-collection-input"]').fill("TEST-ERR");
  await page.locator('[data-testid="sna-add-collection-button"]').click();
  await page.locator('[data-testid="sna-upload-modal-confirm-button"]').click();

  const collectionRow = page.locator('[data-testid^="sna-collection-row-TEST-ERR"]');
  await expect(collectionRow).toBeVisible({ timeout: 15000 });

  const uploadInput = collectionRow.locator('input[id^="rawUpload_"]');

  // --- Error: empty JSON array ---
  const emptyArrayPath = path.resolve(__dirname, "../../tests-assets/empty_array.json");
  await uploadInput.setInputFiles(emptyArrayPath);
  await expect(page.locator('#client-snackbar')).toBeVisible({ timeout: 5000 });
  await page.locator('[aria-label="close"]').click();

  // --- Error: JSON with invalid keys (no id, no tweet/tiktok/post key) ---
  const invalidKeysPath = path.resolve(__dirname, "../../tests-assets/invalid_keys.json");
  await uploadInput.setInputFiles(invalidKeysPath);
  await expect(page.locator('#client-snackbar')).toBeVisible({ timeout: 5000 });
  await page.locator('[aria-label="close"]').click();

  // --- Cleanup ---
  await collectionRow.locator('[data-testid^="sna-delete-button-"]').click();
  await expect(collectionRow).not.toBeVisible({ timeout: 5000 });
});
